INSERT INTO quiz_question (code, subject, chapter, type, difficulty, stem, options, answer, analysis, knowledge) VALUES
('m-001', '高等数学', '极限与连续', 'single', 1, '极限 $\\lim\\limits_{x \\to 0} \\dfrac{\\sin x}{x}$ 的值为：', '["$0$","$1$","$\\\\infty$","不存在"]', '[1]', '这是第一个重要极限。当 $x \\to 0$ 时 $\\sin x$ 与 $x$ 是等价无穷小，故 $\\dfrac{\\sin x}{x} \\to 1$。', '["重要极限","等价无穷小"]'),
('m-002', '高等数学', '极限与连续', 'single', 1, '极限 $\\lim\\limits_{x \\to \\infty} \\left(1 + \\dfrac{1}{x}\\right)^{x}$ 的值为：', '["$1$","$e$","$e^{2}$","$\\\\infty$"]', '[1]', '这是第二个重要极限，其值为自然常数 $e \\approx 2.71828$。', '["重要极限"]'),
('m-003', '高等数学', '极限与连续', 'single', 2, '当 $x \\to 0$ 时，$1 - \\cos x$ 与下列哪个量是同阶无穷小？', '["$x$","$x^{2}$","$x^{3}$","$\\\\sqrt{x}$"]', '[1]', '由 $1 - \\cos x = 2\\sin^{2}\\dfrac{x}{2} \\sim \\dfrac{x^{2}}{2}$ 可知，它与 $x^{2}$ 是同阶（且等价）无穷小。', '["等价无穷小"]'),
('m-004', '高等数学', '极限与连续', 'judge', 1, '判断：函数在某点可导，则它在该点必定连续。', '["正确","错误"]', '[0]', '可导必连续，这是导数定义直接推出的结论；但反之不成立。', '["连续与可导"]'),
('m-005', '高等数学', '极限与连续', 'judge', 2, '判断：函数在某点连续，则它在该点必定可导。', '["正确","错误"]', '[1]', '连续不一定可导。典型反例：$f(x)=|x|$ 在 $x=0$ 处连续但不可导（左右导数不相等）。', '["连续与可导"]'),
('m-006', '高等数学', '导数与微分', 'single', 1, '函数 $f(x) = |x|$ 在 $x = 0$ 处的性质是：', '["连续且可导","连续但不可导","不连续但可导","既不连续也不可导"]', '[1]', '$|x|$ 在 $0$ 处左右极限都等于 $0$，故连续；但左导数为 $-1$、右导数为 $1$，不相等，故不可导。', '["连续与可导","导数定义"]'),
('m-007', '高等数学', '导数与微分', 'single', 1, '求导：$\\dfrac{d}{dx}(\\ln x) = $', '["$\\\\dfrac{1}{x}$","$x$","$-\\\\dfrac{1}{x^{2}}$","$\\\\ln x$"]', '[0]', '自然对数函数的导数为 $\\dfrac{1}{x}$（$x > 0$）。', '["基本求导公式"]'),
('m-008', '高等数学', '导数与微分', 'single', 2, '若 $f''(x_0) = 0$，则 $x_0$ 一定是 $f(x)$ 的极值点。该说法：', '["正确","错误，还需二阶导数等条件判断"]', '[1]', '驻点不一定是极值点。反例：$f(x)=x^{3}$ 在 $x=0$ 处 $f''(0)=0$，但 $0$ 不是极值点。', '["极值与最值"]'),
('m-009', '高等数学', '导数与微分', 'multiple', 2, '罗尔定理成立需要满足的条件包括（多选）：', '["$f(x)$ 在闭区间 $[a,b]$ 上连续","$f(x)$ 在开区间 $(a,b)$ 内可导","$f(a) = f(b)$","$f(x)$ 在 $[a,b]$ 上单调"]', '[0,1,2]', '罗尔定理三条件：闭区间连续、开区间可导、端点函数值相等。单调性不是前提。', '["微分中值定理"]'),
('m-010', '高等数学', '导数与微分', 'single', 2, '曲线 $y = f(x)$ 的拐点是：', '["$f''(x)=0$ 的点","$f''''(x)=0$ 的点","凹凸性发生改变的点","函数值最大的点"]', '[2]', '拐点是曲线凹凸性发生改变的点。$f''''(x)=0$ 只是必要条件（候选点），需进一步判断两侧二阶导数是否变号。', '["凹凸性与拐点"]'),
('m-011', '高等数学', '不定积分', 'single', 1, '求积分：$\\displaystyle\\int \\dfrac{1}{x}\\,dx = $', '["$\\\\ln x + C$","$\\\\ln|x| + C$","$-\\\\dfrac{1}{x^{2}} + C$","$\\\\dfrac{1}{x} + C$"]', '[1]', '注意定义域：$x$ 可能为负，因此正确结果是 $\\ln|x| + C$。', '["基本积分公式"]'),
('m-012', '高等数学', '不定积分', 'single', 1, '求积分：$\\displaystyle\\int e^{x}\\,dx = $', '["$e^{x} + C$","$\\\\dfrac{e^{x}}{x} + C$","$xe^{x} + C$","$\\\\ln x + C$"]', '[0]', '$e^{x}$ 的导数与积分都是它本身。', '["基本积分公式"]'),
('m-013', '高等数学', '定积分', 'single', 2, '定积分 $\\displaystyle\\int_{0}^{1} x^{2}\\,dx$ 的值为：', '["$\\\\dfrac{1}{2}$","$\\\\dfrac{1}{3}$","$\\\\dfrac{1}{4}$","$1$"]', '[1]', '$\\displaystyle\\int_{0}^{1} x^{2}\\,dx = \\left[\\dfrac{x^{3}}{3}\\right]_{0}^{1} = \\dfrac{1}{3}$。', '["定积分计算"]'),
('m-014', '高等数学', '定积分', 'single', 2, '$\\displaystyle\\int_{0}^{\\pi} \\sin x\\,dx = $', '["$0$","$1$","$2$","$\\\\pi$"]', '[2]', '$\\displaystyle\\int_{0}^{\\pi} \\sin x\\,dx = \\big[-\\cos x\\big]_{0}^{\\pi} = -(-1) - (-1) = 2$。', '["定积分计算"]'),
('m-015', '高等数学', '级数', 'single', 3, '级数 $\\displaystyle\\sum_{n=1}^{\\infty} \\dfrac{1}{n^{2}}$ 的敛散性与和为：', '["发散","收敛，和为 $\\\\dfrac{\\\\pi^{2}}{6}$","收敛，和为 $1$","收敛，和为 $e$"]', '[1]', '这是 $p$ 级数 $p=2>1$ 的情形，收敛；欧拉证明了其和为 $\\dfrac{\\pi^{2}}{6} \\approx 1.6449$。', '["无穷级数"]'),
('l-001', '线性代数', '矩阵运算', 'judge', 1, '判断：矩阵乘法一般不满足交换律，即 AB ≠ BA。', '["正确","错误"]', '[0]', '矩阵乘法满足结合律与分配律，但不满足交换律，且 AB 有意义时 BA 未必有意义。', '["矩阵运算"]'),
('l-002', '线性代数', '矩阵运算', 'single', 2, '设 A、B 为同阶方阵，则 (AB)ᵀ = ', '["AᵀBᵀ","BᵀAᵀ","AB","BA"]', '[1]', '转置的乘法法则是「反序」： (AB)ᵀ = BᵀAᵀ。', '["矩阵运算","矩阵转置"]'),
('l-003', '线性代数', '行列式', 'single', 2, '方阵 A 可逆的充分必要条件是：', '["|A| = 0","|A| ≠ 0","A 是对称矩阵","A 的元素全非零"]', '[1]', 'A 可逆 ⟺ |A| ≠ 0 ⟺ r(A) = n ⟺ A 的列向量组线性无关。', '["矩阵可逆性"]'),
('l-004', '线性代数', '行列式', 'judge', 1, '判断：交换行列式的任意两行，行列式的值变号。', '["正确","错误"]', '[0]', '这是行列式的基本性质之一；推论是若两行相同则行列式为 0。', '["行列式性质"]'),
('l-005', '线性代数', '行列式', 'single', 2, '设 A 为 n 阶方阵，则 |Aᵀ| 与 |A| 的关系是：', '["|Aᵀ| = |A|","|Aᵀ| = −|A|","|Aᵀ| = |A|²","无确定关系"]', '[0]', '行列式转置不变，即 |Aᵀ| = |A|。', '["行列式性质"]'),
('l-006', '线性代数', '特征值', 'judge', 2, '判断：若方阵 A 有零特征值，则 A 不可逆。', '["正确","错误"]', '[0]', '|A| 等于全部特征值之积，含零特征值则 |A|=0，故 A 不可逆。', '["特征值与特征向量"]'),
('l-007', '线性代数', '特征值', 'single', 2, 'n 阶方阵 A 所有特征值之和等于：', '["|A|","A 的主对角线元素之和（迹）","r(A)","0"]', '[1]', '特征值之和等于矩阵的迹 tr(A)，特征值之积等于 |A|。', '["特征值与特征向量"]'),
('l-008', '线性代数', '向量组', 'single', 2, '向量组 α₁, α₂, …, αₛ 线性相关的充要条件是：', '["其中每个向量都非零","存在不全为零的数 k₁…kₛ 使 ∑kᵢαᵢ = 0","向量个数 s > 1","向量组秩等于 s"]', '[1]', '线性相关的定义即存在不全为零的系数使线性组合为零向量；秩等于 s 时是线性无关。', '["向量组线性相关性"]'),
('l-009', '线性代数', '向量组', 'single', 3, '设向量组含 s 个 n 维向量，若 s > n，则该向量组：', '["必定线性无关","必定线性相关","可能无关也可能相关","无法判断"]', '[1]', '向量个数超过维数时必线性相关，因为秩 r ≤ n < s。', '["向量组线性相关性"]'),
('l-010', '线性代数', '线性方程组', 'single', 2, 'n 元线性方程组 Ax = b 有唯一解的充要条件是：', '["r(A) = r(A|b) < n","r(A) = r(A|b) = n","r(A) < n","|A| = 0"]', '[1]', '有解要求 r(A)=r(A|b)；唯一解进一步要求秩等于未知数个数 n。', '["线性方程组"]'),
('p-001', '概率论与数理统计', '古典概型', 'single', 1, '同时掷两枚均匀硬币，恰好出现一个正面的概率是：', '["1/4","1/3","1/2","3/4"]', '[2]', '样本空间为 {正正, 正反, 反正, 反反} 共 4 个等可能结果，恰好一个正面的有 2 个，故概率为 2/4 = 1/2。', '["古典概型"]'),
('p-002', '概率论与数理统计', '条件概率', 'single', 2, '设 P(B) > 0，则条件概率 P(A|B) 等于：', '["P(AB)/P(B)","P(A)P(B)","P(A)/P(B)","P(A∪B)"]', '[0]', '条件概率定义为 P(A|B) = P(AB)/P(B)，要求 P(B) > 0。', '["条件概率"]'),
('p-003', '概率论与数理统计', '独立性', 'judge', 2, '判断：若事件 A、B 相互独立，则 P(AB) = P(A)P(B)。', '["正确","错误"]', '[0]', '这正是两事件相互独立的定义（等价于 P(A|B)=P(A)，当 P(B)>0）。', '["事件独立性"]'),
('p-004', '概率论与数理统计', '独立性', 'judge', 3, '判断：若事件 A、B 互斥（互不相容），则 A、B 一定相互独立。', '["正确","错误"]', '[1]', '互斥意味着 P(AB)=0。若 P(A)>0 且 P(B)>0，则 P(A)P(B)>0 ≠ 0，故并不独立。互斥与独立是两个不同的概念。', '["事件独立性","互斥与独立"]'),
('p-005', '概率论与数理统计', '随机变量数字特征', 'single', 2, '设 X 为随机变量，a、b 为常数，则 E(aX + b) = ', '["aE(X) + b","aE(X) + ab","aE(X)","E(X) + b"]', '[0]', '数学期望具有线性性质：E(aX+b) = aE(X) + b。', '["数学期望"]'),
('p-006', '概率论与数理统计', '随机变量数字特征', 'single', 3, '设 X 为随机变量，a、b 为常数，则 D(aX + b) = ', '["aD(X) + b","a²D(X)","a²D(X) + b","aD(X)"]', '[1]', '方差对常数加项不敏感，对系数要平方：D(aX+b) = a²D(X)。', '["方差"]'),
('p-007', '概率论与数理统计', '常见分布', 'single', 2, '标准正态分布的记号和参数是：', '["N(1, 0)","N(0, 1)","N(0, 0)","N(1, 1)"]', '[1]', '正态分布 N(μ, σ²)，标准正态分布指 μ=0、σ²=1，即 N(0,1)。', '["常见分布"]'),
('p-008', '概率论与数理统计', '常见分布', 'single', 2, '若 X ~ N(μ, σ²)，则 (X − μ)/σ 服从：', '["N(μ, σ²)","N(0, 1)","N(0, σ²)","均匀分布"]', '[1]', '标准化变换后服从标准正态分布 N(0,1)。', '["常见分布","随机变量标准化"]'),
('p-009', '概率论与数理统计', '大数定律与中心极限定理', 'single', 3, '中心极限定理主要说明：', '["独立同分布随机变量之和的标准化近似服从正态分布","随机变量一定有期望","样本均值等于总体均值","方差一定存在"]', '[0]', '在独立同分布且方差有限的条件下，n 充分大时样本均值（或和的标准化）近似服从正态分布。', '["中心极限定理"]'),
('e-001', '大学英语', '词汇辨析', 'single', 1, 'The word "abandon" most probably means:', '["to give up completely","to take care of","to increase quickly","to remember clearly"]', '[0]', 'abandon 意为「放弃、抛弃」，与 give up completely 对应。', '["词汇辨析"]'),
('e-002', '大学英语', '词汇辨析', 'single', 2, 'Choose the word closest in meaning to "compulsory":', '["optional","required","temporary","complicated"]', '[1]', 'compulsory 意为「强制的、必修的」，与 required 同义；optional 是它的反义词。', '["词汇辨析"]'),
('e-003', '大学英语', '词汇辨析', 'single', 2, 'His explanation was so ______ that nobody could understand it.', '["ambiguous","obvious","transparent","frank"]', '[0]', '由后半句「没人能听懂」可知需要表示「模糊不清」的词，ambiguous 意为「模棱两可的」。', '["词汇辨析"]'),
('e-004', '大学英语', '虚拟语气', 'single', 2, 'If I ______ you, I would accept the offer.', '["am","was","were","will be"]', '[2]', '与现在事实相反的虚拟条件句，从句用过去式，be 动词统一用 were。', '["虚拟语气"]'),
('e-005', '大学英语', '虚拟语气', 'single', 3, 'The professor suggested that the students ______ the experiment again.', '["did","do","does","doing"]', '[1]', 'suggest 表示「建议」时，宾语从句用 (should) + 动词原形的虚拟语气。', '["虚拟语气"]'),
('e-006', '大学英语', '时态语态', 'single', 2, 'By the time we arrived, the lecture ______ already ______.', '["has / begun","had / begun","was / beginning","would / begin"]', '[1]', '「过去的过去」用过去完成时 had + 过去分词，begin 的过去分词是 begun。', '["时态与语态"]'),
('e-007', '大学英语', '时态语态', 'single', 2, 'The new library ______ by the end of next year.', '["will complete","will be completed","is completing","has completed"]', '[1]', '图书馆是「被建成」的，且时间为将来，故用一般将来时的被动语态 will be completed。', '["时态与语态","被动语态"]'),
('e-008', '大学英语', '固定搭配', 'single', 2, 'Students are required to ______ full advantage of the library resources.', '["take","make","get","do"]', '[0]', '固定搭配 take advantage of，意为「利用」。', '["固定搭配"]'),
('e-009', '大学英语', '定语从句', 'single', 2, 'This is the laboratory ______ we carried out the research last term.', '["which","where","that","who"]', '[1]', '先行词是表示地点的 laboratory，从句中缺地点状语，故用关系副词 where（= in which）。', '["定语从句"]'),
('e-010', '大学英语', '非谓语动词', 'single', 3, '______ from the top of the hill, the campus looks like a beautiful garden.', '["Seeing","Seen","To see","Having seen"]', '[1]', 'campus 与 see 之间是被动关系（校园被看），故用过去分词 Seen 作状语。', '["非谓语动词"]'),
('c-001', '计算机基础', '数据表示', 'single', 1, '在计算机中，1 KB 等于多少字节（Byte）？', '["1000","1024","512","2048"]', '[1]', '计算机采用二进制，1 KB = 2¹⁰ B = 1024 B。（硬盘厂商有时按 1000 计算，属十进制标称。）', '["数制转换","存储单位"]'),
('c-002', '计算机基础', '数据表示', 'single', 1, '二进制数 1011 转换为十进制是：', '["9","11","13","15"]', '[1]', '1×2³ + 0×2² + 1×2¹ + 1×2⁰ = 8 + 0 + 2 + 1 = 11。', '["数制转换"]'),
('c-003', '计算机基础', '数据表示', 'single', 2, '十进制数 25 转换为二进制是：', '["11001","10101","11010","10011"]', '[0]', '25 = 16 + 8 + 1 = 11001₂。', '["数制转换"]'),
('c-004', '计算机基础', '操作系统', 'multiple', 2, '下列属于操作系统主要功能的有（多选）：', '["进程管理","存储管理","文件管理","编译高级语言源代码"]', '[0,1,2]', '操作系统负责进程、存储、文件、设备管理及用户接口；编译源代码是编译器的职责。', '["操作系统"]'),
('c-005', '计算机基础', '计算机网络', 'single', 2, 'TCP/IP 模型中，IP 协议工作在：', '["应用层","传输层","网际层（网络层）","网络接口层"]', '[2]', 'IP 是网际层协议，负责寻址与路由；TCP 属于传输层，HTTP 属于应用层。', '["计算机网络","网络分层"]'),
('c-006', '计算机基础', '计算机网络', 'single', 2, 'HTTP 协议默认使用的端口号是：', '["21","25","80","443"]', '[2]', 'HTTP 默认端口 80；HTTPS 默认 443；FTP 为 21；SMTP 为 25。', '["计算机网络","网络协议"]');
INSERT INTO quiz_question (code, subject, chapter, type, difficulty, stem, options, answer, analysis, knowledge) VALUES
('c-007', '计算机基础', '计算机网络', 'single', 2, 'TCP 与 UDP 的主要区别是：', '["TCP 面向连接可靠传输，UDP 无连接不保证可靠","TCP 速度一定更快","UDP 不能用于视频","两者完全相同"]', '[0]', 'TCP 提供面向连接的可靠字节流服务；UDP 无连接、开销小但不保证可靠，适合实时音视频等场景。', '["计算机网络","网络协议"]'),
('c-008', '计算机基础', '数据库', 'single', 2, 'SQL 中用于从表中查询数据的关键字是：', '["SELECT","UPDATE","INSERT","DELETE"]', '[0]', 'SELECT 用于查询；INSERT 插入、UPDATE 更新、DELETE 删除，合称增删改查（CRUD）。', '["数据库基础"]'),
('d-001', '数据结构', '线性表', 'single', 1, '栈（Stack）的存取特点是：', '["先进先出","后进先出","随机存取","按优先级存取"]', '[1]', '栈是 LIFO（Last In First Out）结构，只允许在栈顶插入和删除。', '["栈与队列"]'),
('d-002', '数据结构', '线性表', 'single', 1, '队列（Queue）的存取特点是：', '["先进先出","后进先出","随机存取","双向存取"]', '[0]', '队列是 FIFO（First In First Out）结构，队尾入队、队头出队。', '["栈与队列"]'),
('d-003', '数据结构', '线性表', 'single', 2, '与数组相比，链表的主要优势是：', '["支持随机访问","插入和删除元素效率高","占用内存更少","查找速度更快"]', '[1]', '链表插入删除只需修改指针，为 O(1)（已知位置时）；但链表不支持随机访问，查找需 O(n)。', '["线性表"]'),
('d-004', '数据结构', '树', 'single', 2, '对二叉搜索树（BST）进行中序遍历，得到的序列是：', '["无序的","递增有序的","递减有序的","按层次排列的"]', '[1]', 'BST 满足左子树 < 根 < 右子树，中序遍历（左-根-右）恰好得到递增有序序列。', '["树与二叉树","二叉搜索树"]'),
('d-005', '数据结构', '树', 'single', 3, '一棵有 n 个结点的完全二叉树，其深度（层数）为：', '["⌊log₂n⌋ + 1","n / 2","log₂n","n − 1"]', '[0]', '完全二叉树深度为 ⌊log₂n⌋ + 1（根结点所在层为第 1 层）。', '["树与二叉树","二叉树性质"]'),
('d-006', '数据结构', '树', 'single', 2, '一棵二叉树中，度为 2 的结点数为 5，则叶子结点数为：', '["4","5","6","无法确定"]', '[2]', '二叉树性质：叶子数 n₀ = 度为 2 的结点数 n₂ + 1 = 5 + 1 = 6。', '["树与二叉树","二叉树性质"]'),
('d-007', '数据结构', '排序', 'single', 2, '快速排序的平均时间复杂度是：', '["O(n)","O(n log n)","O(n²)","O(log n)"]', '[1]', '快排平均 O(n log n)；最坏情况（每次划分极不平衡）退化为 O(n²)。', '["排序算法","算法复杂度"]'),
('d-008', '数据结构', '排序', 'single', 2, '冒泡排序在最坏情况下的时间复杂度是：', '["O(n)","O(n log n)","O(n²)","O(log n)"]', '[2]', '最坏（逆序）需进行约 n(n−1)/2 次比较与交换，故为 O(n²)。', '["排序算法","算法复杂度"]'),
('d-009', '数据结构', '排序', 'multiple', 3, '下列排序算法中，平均时间复杂度为 O(n log n) 的有（多选）：', '["快速排序","归并排序","堆排序","直接插入排序"]', '[0,1,2]', '快排、归并、堆排序平均均为 O(n log n)；直接插入排序平均为 O(n²)。', '["排序算法","算法复杂度"]'),
('d-010', '数据结构', '查找', 'single', 2, '对长度为 n 的有序表进行二分查找，时间复杂度为：', '["O(1)","O(log n)","O(n)","O(n log n)"]', '[1]', '每次比较将查找区间缩小一半，最多比较 ⌈log₂(n+1)⌉ 次，故为 O(log n)。', '["查找算法","算法复杂度"]'),
('d-011', '数据结构', '图', 'single', 3, '具有 n 个顶点的无向完全图，其边数为：', '["n(n−1)/2","n(n−1)","n²","n−1"]', '[0]', '每两个顶点之间恰有一条边，组合数 C(n,2) = n(n−1)/2。', '["图论基础"]'),
('ph-001', '大学物理', '质点运动学', 'single', 1, '牛顿第二定律的表达式是：', '["F = ma","F = mv","F = m/a","F = a/m"]', '[0]', '牛顿第二定律：物体加速度与合外力成正比、与质量成反比，即 F = ma。', '["牛顿运动定律"]'),
('ph-002', '大学物理', '动量守恒', 'single', 2, '系统动量守恒的条件是：', '["系统不受外力或合外力为零","系统动能守恒","系统内无摩擦","系统机械能守恒"]', '[0]', '动量守恒条件是合外力为零（或外力远小于内力可忽略）。注意动量守恒与机械能守恒是两回事。', '["动量守恒"]'),
('ph-003', '大学物理', '机械能', 'judge', 2, '判断：只有保守力做功时，系统的机械能守恒。', '["正确","错误"]', '[0]', '机械能守恒条件：除重力、弹力等保守力外，其他力不做功（或做功代数和为零）。', '["机械能守恒"]'),
('ph-004', '大学物理', '稳恒电流', 'single', 1, '两个电阻 R₁、R₂ 串联后的总电阻为：', '["R₁ + R₂","R₁R₂/(R₁+R₂)","1/(R₁+R₂)","R₁ − R₂"]', '[0]', '串联电阻相加：R = R₁ + R₂；并联才是 R₁R₂/(R₁+R₂)。', '["电路基础"]'),
('ph-005', '大学物理', '静电场', 'single', 2, '点电荷 q 在距离 r 处产生的电场强度大小为（k 为静电力常量）：', '["kq/r","kq/r²","kq²/r²","kq/r³"]', '[1]', '点电荷场强公式 E = kq/r²，方向沿连线（正电荷向外）。', '["静电场"]'),
('ph-006', '大学物理', '光的干涉', 'single', 2, '在双缝干涉实验中，相邻两条明纹的间距 Δx 与波长 λ 的关系是：', '["Δx 与 λ 成正比","Δx 与 λ 成反比","Δx 与 λ 无关","Δx 与 λ² 成正比"]', '[0]', '由 Δx = Dλ/d 可知，条纹间距与波长成正比，波长越长条纹越宽。', '["光的干涉"]'),
('ph-007', '大学物理', '热学', 'single', 2, '理想气体状态方程为：', '["pV = nRT","pV = nT","p/V = nRT","V = nRT"]', '[0]', '理想气体状态方程 pV = nRT，其中 n 为物质的量，R 为普适气体常量。', '["理想气体"]'),
('ph-008', '大学物理', '波动', 'single', 3, '机械波在介质中传播时，传播的是：', '["介质质点本身","振动状态（能量与相位）","介质质量","静电场"]', '[1]', '波传播的是振动状态与能量，介质质点只在各自平衡位置附近振动，并不随波迁移。', '["机械波"]'),
('z-001', '思想政治', '马克思主义基本原理', 'single', 2, '马克思主义哲学认为，世界的本原是：', '["物质","精神","理念","上帝"]', '[0]', '辩证唯物主义认为物质是世界的本原，物质决定意识，意识是物质世界长期发展的产物。', '["物质与意识"]'),
('z-002', '思想政治', '马克思主义基本原理', 'judge', 2, '判断：实践是检验真理的唯一标准。', '["正确","错误"]', '[0]', '真理是主观与客观相符合，只有实践才能把主观认识与客观实际联系起来加以检验。', '["真理与实践"]'),
('z-003', '思想政治', '马克思主义基本原理', 'single', 2, '矛盾的两个基本属性是：', '["同一性和斗争性","普遍性和特殊性","主要和次要","内因和外因"]', '[0]', '矛盾即对立统一，同一性（相互依存、相互转化）与斗争性（相互排斥、相互对立）是其基本属性。', '["矛盾观"]'),
('ec-001', '经济学基础', '微观经济学', 'single', 2, '在其他条件不变时，某商品价格上升，通常会导致其需求量：', '["增加","减少","不变","先增后减"]', '[1]', '这是需求定理：价格与需求量反向变动（吉芬商品等特例除外）。', '["需求与供给"]'),
('ec-002', '经济学基础', '微观经济学', 'single', 3, '需求价格弹性系数 |Ed| > 1 时，该商品需求：', '["缺乏弹性","富有弹性","单位弹性","完全无弹性"]', '[1]', '|Ed| > 1 为富有弹性（如奢侈品）；|Ed| < 1 为缺乏弹性（如生活必需品）；= 1 为单位弹性。', '["需求价格弹性"]'),
('ec-003', '经济学基础', '宏观经济学', 'single', 2, '国内生产总值（GDP）衡量的是：', '["一国境内一定时期内生产的最终产品和服务的市场价值","一国居民的全部存款","一国的出口总额","一国的财政收入"]', '[0]', 'GDP 按国土原则统计，指一定时期内一国（地区）境内生产的全部最终产品和服务的市场价值。', '["宏观经济核算"]'),
('mg-001', '管理学基础', '管理职能', 'multiple', 2, '管理的四大基本职能包括（多选）：', '["计划","组织","领导","控制"]', '[0,1,2,3]', '法约尔等提出的管理职能通常概括为计划、组织、领导、控制四项。', '["管理职能"]'),
('mg-002', '管理学基础', '决策', 'single', 2, '西蒙提出的「有限理性」决策模型认为，管理者实际追求的是：', '["最优解","满意解","随机解","唯一解"]', '[1]', '由于信息、时间和认知的限制，决策者遵循「满意原则」而非「最优原则」。', '["决策理论"]'),
('la-001', '法学基础', '宪法', 'single', 2, '我国的根本大法是：', '["宪法","民法典","刑法","教育法"]', '[0]', '宪法是国家的根本大法，具有最高法律效力，是其他法律的立法依据。', '["宪法"]'),
('la-002', '法学基础', '民法典', 'single', 3, '根据《民法典》，完全民事行为能力人的年龄起点一般是：', '["16 周岁","18 周岁","20 周岁","14 周岁"]', '[1]', '十八周岁以上的自然人为成年人，具有完全民事行为能力；十六周岁以上以自己劳动收入为主要生活来源的，视为完全民事行为能力人。', '["民法典"]'),
('f-001', '高等数学', '导数与微分', 'fill', 1, '填空：函数 f(x) = x² 的导数为 f′(x) = ______ 。', NULL, '["2x","2*x"]', '由幂函数求导公式 (xⁿ)′ = n·xⁿ⁻¹，得 (x²)′ = 2x。', '["基本求导公式"]'),
('f-002', '高等数学', '不定积分', 'fill', 1, '填空：∫ cos x dx = ______ + C。', NULL, '["sin x","sinx","sin(x)"]', 'cos x 的原函数是 sin x，因为 (sin x)′ = cos x。', '["基本积分公式"]'),
('f-003', '高等数学', '极限与连续', 'fill', 2, '填空：lim(x→0) (sin x)/x = ______ 。', NULL, '["1"]', '第一个重要极限，值为 1。', '["重要极限"]'),
('f-004', '线性代数', '行列式', 'fill', 2, '填空：二阶行列式 |1 2; 3 4| 的值为 ______ 。', NULL, '["-2","−2","-2.0"]', '二阶行列式 = 1×4 − 2×3 = 4 − 6 = −2（主对角线之积减副对角线之积）。', '["行列式计算"]'),
('f-005', '线性代数', '矩阵运算', 'fill', 2, '填空：n 阶方阵 A 可逆的充要条件是其行列式 |A| ______ 0（填「等于」或「不等于」）。', NULL, '["不等于","≠","不为"]', 'A 可逆 ⟺ |A| ≠ 0。', '["矩阵可逆性"]'),
('f-006', '概率论与数理统计', '常见分布', 'fill', 2, '填空：标准正态分布记作 N(0, 1)，其数学期望 E(X) = ______ 。', NULL, '["0"]', '标准正态分布 N(0,1) 的期望为 0，方差为 1。', '["常见分布","数学期望"]'),
('f-007', '概率论与数理统计', '随机变量数字特征', 'fill', 3, '填空：若 X 的方差 D(X) = 4，则 D(2X) = ______ 。', NULL, '["16"]', 'D(aX) = a²D(X) = 2² × 4 = 16。', '["方差"]'),
('f-008', '计算机基础', '数据表示', 'fill', 1, '填空：十进制数 10 转换为二进制是 ______ 。', NULL, '["1010"]', '10 = 8 + 2 = 1010₂。', '["数制转换"]'),
('f-009', '计算机基础', '数据表示', 'fill', 2, '填空：十六进制数 FF 转换为十进制是 ______ 。', NULL, '["255"]', 'F 表示 15，故 FF₁₆ = 15×16 + 15 = 255。', '["数制转换"]'),
('f-010', '数据结构', '排序', 'fill', 2, '填空：冒泡排序在最坏情况下的时间复杂度为 O(______)。（用 n 表示，如 n² 写作 n^2 或 n2）', NULL, '["n^2","n²","n2","n*n"]', '最坏（完全逆序）需约 n(n−1)/2 次比较交换，故为 O(n²)。', '["排序算法","算法复杂度"]'),
('f-011', '数据结构', '树', 'fill', 2, '填空：一棵二叉树中度为 2 的结点有 4 个，则叶子结点有 ______ 个。', NULL, '["5"]', '由 n₀ = n₂ + 1 = 4 + 1 = 5。', '["树与二叉树","二叉树性质"]'),
('f-012', '大学物理', '稳恒电流', 'fill', 1, '填空：两个 10 Ω 的电阻并联后的总电阻为 ______ Ω。', NULL, '["5","5Ω","5欧","5ohm"]', '并联公式 1/R = 1/R₁ + 1/R₂ = 1/10 + 1/10 = 1/5，故 R = 5 Ω。', '["电路基础"]'),
('f-013', '大学物理', '质点运动学', 'fill', 2, '填空：自由落体运动中，物体下落的加速度大小约为 ______ m/s²（取整数）。', NULL, '["9.8","10","9.80"]', '重力加速度 g ≈ 9.8 m/s²，粗略计算时常取 10 m/s²。', '["牛顿运动定律"]'),
('f-014', '大学英语', '词汇辨析', 'fill', 2, '填空：The opposite of "increase" is ______ .（填一个英文单词）', NULL, '["decrease","reduce","decline","diminish"]', 'increase（增加）的反义词是 decrease（减少），也可用 reduce / decline / diminish。', '["词汇辨析"]'),
('f-015', '大学英语', '时态语态', 'fill', 2, '填空：He ______ (go) to the library yesterday.（用所给词的正确形式填空）', NULL, '["went"]', 'yesterday 表明是过去时间，用一般过去时，go 的过去式为 went。', '["时态与语态"]'),
('f-016', '经济学基础', '微观经济学', 'fill', 3, '填空：当需求价格弹性 |Ed| = 1 时，称为 ______ 弹性。', NULL, '["单位","单位弹性","单一"]', '|Ed| = 1 称单位弹性；> 1 富有弹性；< 1 缺乏弹性。', '["需求价格弹性"]'),
('s-001', '学习方法', '记忆规律', 'single', 1, '根据艾宾浩斯遗忘曲线，遗忘的进程是：', '["先快后慢","先慢后快","匀速进行","随机波动"]', '[0]', '遗忘在学习之后立即开始，最初速度很快，之后逐渐减慢。因此及时复习（如当天、次日）效果最好。', '["记忆规律"]'),
('s-002', '学习方法', '练习策略', 'single', 2, '「间隔重复」（Spaced Repetition）的核心做法是：', '["一次性长时间集中复习","把复习分散到逐渐拉长的时间间隔中","只复习新内容","只做难题"]', '[1]', '间隔重复通过在遗忘临界点安排复习，用较少总时间获得更牢固的长期记忆。', '["间隔重复"]'),
('s-003', '学习方法', '练习策略', 'judge', 2, '判断：做题后立即核对解析、分析错误原因，比只对答案更有利于提分。', '["正确","错误"]', '[0]', '错题归因（是概念不清、计算失误还是审题问题）决定了后续补救方向，是提分的关键环节。', '["错题归因"]');
